example.code:
resource "aws_ami" "ubuntu" {
  most_recent = true
}
data "aws_instance" "web" {
  ami = "ami-123"
}

# same config, per-workspace state; name available as a variable
terraform {
  backend "s3" {
    bucket = "my-tf-state"
    key    = "app/terraform.tfstate"  # workspaces append /env:/<name> automatically
    region = "us-east-1"
  }
}
resource "aws_instance" "web" {
  count         = terraform.workspace == "prod" ? 3 : 1
  instance_type = terraform.workspace == "prod" ? "m5.large" : "t3.micro"
}

# variables.tf — declare once
variable "instance_type" {
  type = string
  validation {
    condition     = contains(["t3.micro", "m5.large"], var.instance_type)
    error_message = "Instance type must be an approved size."
  }
}
# dev.tfvars:  instance_type = "t3.micro"
# prod.tfvars: instance_type = "m5.large"
# apply: terraform apply -var-file=prod.tfvars

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"   # >= 5.0, < 6.0 : bugfixes and features, no breaking major
    }
  }
}
# .terraform.lock.hcl then pins the EXACT build, e.g. 5.31.0, with hashes

# the modern pattern: no static secrets anywhere
provider "aws" {
  region = "us-east-1"
  assume_role {
    role_arn    = "arn:aws:iam::123456789012:role/TerraformDeployer"
    external_id = var.deploy_external_id   # from secrets manager, never git
  }
}
# locally: SSO / aws sso login. CI: OIDC federation. Nowhere: AKIA... in a file.

# network.tftest.hcl — native test file
run "vpc_creates_subnets" {
  command = plan
  assert {
    condition     = length(aws_subnet.main) == 2
    error_message = "Expected 2 subnets, got ${length(aws_subnet.main)}"
  }
  assert {
    condition     = aws_vpc.main.cidr_block == "10.0.0.0/16"
    error_message = "VPC CIDR mismatch"
  }
}

# tags enforced at the provider level — every resource inherits them
provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "terraform"
      Owner       = var.team
      CostCenter  = var.cost_center
    }
  }
}
# plus policy: every resource must resolve Owner/Environment/CostCenter

# explicit desired state: every meaningful attribute stated
resource "aws_instance" "web" {
  ami                    = data.aws_ami.ubuntu.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.main.id
  vpc_security_group_ids = [aws_security_group.web.id]
  root_block_device {
    volume_size = 30
    encrypted   = true   # explicit: never inherit a default for this
  }
  tags = { Name = "web-1" }
}

# for_each: stable keys survive membership changes
variable "subnets" {
  type = map(object({ cidr = string, az = string }))
  default = {
    "a" = { cidr = "10.0.1.0/24", az = "us-east-1a" }
    "b" = { cidr = "10.0.2.0/24", az = "us-east-1b" }
  }
}
resource "aws_subnet" "main" {
  for_each          = var.subnets
  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az
}

resource "aws_db_instance" "main" {
  # ... configuration ...
  lifecycle {
    prevent_destroy = true   # destroying this requires removing this line first (a reviewed PR)
  }
}
resource "aws_launch_template" "web" {
  name_prefix = "web-"      # unique names allow create-before-destroy
  # ...
  lifecycle { create_before_destroy = true }
}

terraform {
  backend "s3" {
    bucket         = "my-tf-state-prod"
    key            = "network/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "tf-locks-prod"
  }
}
# per-env values via: terraform init -backend-config=prod.hcl -reconfigure

# the root as wiring diagram: data flows through outputs
module "network" {
  source = "./modules/network"
  cidr   = "10.0.0.0/16"
}
module "compute" {
  source     = "./modules/compute"
  subnet_ids = module.network.private_subnet_ids  # explicit data flow
  vpc_id     = module.network.vpc_id
}

module "vpc" {
  source  = "app.terraform.io/acme/vpc/aws"
  version = "~> 3.0"   # pinned: bugfixes and features, no breaking majors
  cidr    = "10.0.0.0/16"
}
# vs the dangerous: source = "git::https://github.com/acme/tf-vpc.git"  (unpinned!)

variable "environment" {
  description = "Deployment environment (dev, staging, prod). Used in naming and tagging."
  type        = string
  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "Environment must be dev, staging, or prod."
  }
}
output "vpc_id" {
  description = "ID of the created VPC, for wiring compute modules."
  value       = aws_vpc.main.id
}

# the pattern: reference, don't embed
variable "db_password" {
  type      = string
  sensitive = true
  # value comes from TF_VAR_db_password (CI secret) or a vault data source — never the repo
}
data "aws_secretsmanager_secret_version" "db" {
  secret_id = "prod/db/password"   # read at apply time; rotation needs no config change
}

